changeSet.sql:

if exists (select * from [INFORMATION_SCHEMA].[ROUTINES] where SPECIFIC_SCHEMA = 'integration' and SPECIFIC_NAME = 'ProcessExecutionAssets')
begin
	drop procedure [integration].[ProcessExecutionAssets];
end

changeSet.rollback:
create or alter procedure [integration].[ProcessExecutionAssets] @ExecutionID bigint, @SynchedAssetTypeID int, @RequestNumber int, @AssetTypeID int, @ResourceID int, @Section int as begin set nocount on;
declare @date datetime = getutcdate(), @IsFullRefresh bit = 0
select @IsFullRefresh = IsFullRefresh from integration.ExecutionAssetType where ExecutionID = @ExecutionID and SynchedAssetTypeID = @SynchedAssetTypeID;
if @Section = 0 begin declare @Object varchar(50), @ObjectID int, @OptionalID int, @TriggerTopicMessage bit, @Level int, @ParentIntersectTypeID int;
select @Object = [Object], @ObjectID = [ObjectID], @OptionalID = [OptionalID], @TriggerTopicMessage = [TriggerTopicMessage], @Level = [Level] from integration.SynchedAssetType where ID = @SynchedAssetTypeID;
select @ParentIntersectTypeID = IT.ID from IntersectType IT inner join [Predicate] P on P.ID = IT.PredicateID and IT.Object = @Object and IT.ObjectID = @ObjectID and P.[Type] = case @Object when 'PolicyType' then 4 when 'TaxonomyType' then 4 else 3 end
begin try update R set R.[Action] = 'U', R.RequestNumber = @RequestNumber from integration.AssetHash R inner join Asset A on A.AssetTypeID = @AssetTypeID and A.SourceID = R.SourceID left join [Intersect] I on I.IntersectTypeID = @ParentIntersectTypeID and I.Object = A.Object and I.ObjectID = A.ObjectID where R.SynchedAssetTypeID = @SynchedAssetTypeID and R.Section = 1 and @ParentIntersectTypeID is not null and I.ID is null; end try begin catch -- ERROR CODE: 1 update integration.ExecutionAssetType set ErrorMessage = coalesce(ErrorMessage, '') + '; ' + ERROR_MESSAGE() where ExecutionID = @ExecutionID and SynchedAssetTypeID = @SynchedAssetTypeID end catch
drop table if exists #Assets;
create table #Assets (AssetTypeID int, SourceID varchar(100), AssetID bigint, [Object] varchar(50), ObjectID int, [Type] varchar(50), TypeID int, ParentSourceID nvarchar(250), [Action] char(1), Error nvarchar(max)); CREATE CLUSTERED INDEX CIX_TempAssets ON #Assets (SourceID) CREATE NONCLUSTERED INDEX [IX_TempAssets_Action] ON #Assets ( [Action] ASC ) CREATE NONCLUSTERED INDEX [IX_TempAssets_SourceID-Action] ON #Assets ( SourceID ASC, [Action] ASC )
insert into #Assets (AssetTypeID, SourceID, AssetID, [Object], ObjectID, [Type], TypeID) select A.AssetTypeID, R.SourceID, A.ID, A.Object, A.ObjectID, @Object, @ObjectID from integration.AssetHash R left join Asset A on A.AssetTypeID = @AssetTypeID and A.SourceID = R.SourceID where R.SynchedAssetTypeID = @SynchedAssetTypeID and R.Section = 1 and R.RequestNumber = @RequestNumber and R.[Action] in ('A', 'U') group by A.AssetTypeID, R.SourceID, A.ID, A.Object, A.ObjectID, R.SourceID;
drop table if exists #Context;
create table #Context (SourceID nvarchar(250), RawValue nvarchar(max), [ParentContextPosition] int);
insert into #Context select A.SourceID, RF.FieldValue, F.[ParentContextPosition] from integration.AssetHash A inner join integration.AssetField RF on A.SynchedAssetTypeID = RF.SynchedAssetTypeID and RF.Section = A.Section and RF.SourceID = A.SourceID and RF.FieldName = '_context' inner join [integration].[SynchedAssetTypeFieldItem] F on F.SynchedAssetTypeID = A.SynchedAssetTypeID and F.SourceField = RF.FieldName inner join integration.SynchedAssetType SAT on SAT.ID = A.SynchedAssetTypeID where A.SynchedAssetTypeID = @SynchedAssetTypeID and A.RequestNumber = @RequestNumber and A.Section = 1 and A.[Action] in ('A', 'U') and F.ArrayValueDelimiter is null and F.Active = 1;
BEGIN declare @ParentContextPosition int; select top 1 @ParentContextPosition = [ParentContextPosition] from #Context
if @ParentContextPosition = 99 begin update T set T.ParentSourceID = S.ParentSourceID from #Assets T inner join ( select J.SourceID, max(C.[key]) as [key] from #Context J cross apply OPENJSON(J.RawValue) C cross apply OPENJSON(c.value) with (ParentSourceID nvarchar(500) '$._id') P group by J.SourceID ) MContext on MContext.SourceID = T.SourceID inner join ( select J.SourceID, P.ParentSourceID, C.[key] from #Context J cross apply OPENJSON(J.RawValue) C cross apply OPENJSON(c.value) with (ParentSourceID nvarchar(500) '$._id') P ) S on S.SourceID = T.SourceID and S.[key] = MContext.[key]; end else begin update T set T.ParentSourceID = S.ParentSourceID from #Assets T inner join ( select J.SourceID, P.ParentSourceID, C.[key] from #Context J cross apply OPENJSON(J.RawValue) C cross apply OPENJSON(c.value) with (ParentSourceID nvarchar(500) '$._id') P where C.[key] = J.[ParentContextPosition] ) S on S.SourceID = T.SourceID; end END
update #Assets set [Action] = IIF(AssetID is null, 'A', 'U');
if @Object = 'FusionAttributeType' begin insert into FusionAttribute (FusionAttributeTypeID, FusionID, ParentID, SourceID, Name) select @ObjectID, @OptionalID, P.ObjectID, C.SourceID, substring(RF.FieldValue, 1, 250) as Name from #Assets C inner join integration.AssetField RF on RF.SynchedAssetTypeID = @SynchedAssetTypeID and RF.Section = 1 and RF.SourceID = C.SourceID and RF.FieldName = '_name' and C.[Action] = 'A' left join Asset P on P.SourceID = C.ParentSourceID
update T set T.Object = 'FusionAttribute', T.ObjectID = S.ID from #Assets T inner join FusionAttribute S on S.FusionAttributeTypeID = @ObjectID and S.SourceID = T.SourceID
update T set T.ParentID = S.ParentID from FusionAttribute T inner join ( select P.ObjectID as ParentID, C.ObjectID as ID from #Assets C inner join Asset P on P.SourceID = C.ParentSourceID where [Action] = 'U' ) S on S.ID = T.ID
update H set H.UpdateHash = '0' from integration.AssetHash H inner join #Assets C on C.SourceID = H.SourceID and C.ParentSourceID is not null inner join FusionAttribute F on F.SourceID = C.SourceID and F.ParentID is null where H.RequestNumber = @RequestNumber and H.Section = @Section; end if @Object = 'ReferenceItemType' begin insert into Asset (AssetTypeID, SourceID, [Object], CreatedBy, UpdatedBy, Code) select T.ID, A.SourceID, replace(@Object, 'Type', ''), @ResourceID, @ResourceID, RF.FieldValue from #Assets A inner join AssetType T on T.[Object] = @Object and T.ObjectID = @ObjectID inner join integration.AssetField RF on RF.SynchedAssetTypeID = @SynchedAssetTypeID and RF.Section = 1 and RF.SourceID = A.SourceID and RF.FieldName = '_name' and A.[Action] = 'A' where A.[Action] = 'A'
update T set T.Object = replace(@Object, 'Type', ''), T.ObjectID = S.ObjectID from #Assets T inner join Asset S on S.SourceID = T.SourceID inner join AssetType P on P.ID = S.AssetTypeID and P.[Object] = @Object and P.ObjectID = @ObjectID end if @Object = 'RuleType' begin insert into dbo.[Rule] (RuleTypeID, SourceID, CreatedBy, UpdatedBy) select @ObjectID, SourceID, @ResourceID, @ResourceID from #Assets where [Action] = 'A'
update T set T.Object = 'Rule', T.ObjectID = S.ID from #Assets T inner join [Rule] S on S.RuleTypeID = @ObjectID and S.SourceID = T.SourceID end if @Object = 'ArtifactType' or @Object = 'PolicyType' or @Object = 'TaxonomyType' begin insert into Asset (AssetTypeID, SourceID, [Object], CreatedBy, UpdatedBy) select T.ID, A.SourceID, replace(@Object, 'Type', ''), @ResourceID, @ResourceID from #Assets A inner join AssetType T on T.[Object] = @Object and T.ObjectID = @ObjectID where A.[Action] = 'A'
update T set T.Object = replace(@Object, 'Type', ''), T.ObjectID = S.ObjectID from #Assets T inner join Asset S on S.SourceID = T.SourceID inner join AssetType P on P.ID = S.AssetTypeID and P.[Object] = @Object and P.ObjectID = @ObjectID end
if @ParentIntersectTypeID is not null begin merge into [Intersect] T using ( select @ParentIntersectTypeID as IntersectTypeID, P.Object as Subject, P.ObjectID as SubjectID, C.Object, C.ObjectID from #Assets C inner join Asset P on P.SourceID = C.ParentSourceID where C.[Action] in ('A', 'U') and C.Object is not null and C.ObjectID is not null ) S on (T.IntersectTypeID = S.IntersectTypeID and T.Object = S.Object and T.ObjectID = S.ObjectID) when matched and ( (T.Subject <> S.Subject) OR (T.SubjectID <> S.SubjectID) ) then update set T.Subject = S.Subject, T.SubjectID = S.SubjectID, T.UpdatedBy = @ResourceID when not matched by target then insert (IntersectTypeID, Subject, SubjectID, Object, ObjectID, CreatedBy, UpdatedBy) values (S.IntersectTypeID, S.Subject, S.SubjectID, S.Object, S.ObjectID, @ResourceID, @ResourceID); end;
update T set T.AssetID = S.ID, T.Object = S.Object, T.ObjectID = S.ObjectID from #Assets T inner join Asset S on S.AssetTypeID = T.AssetTypeID and S.SourceID = T.SourceID and T.[Action] = 'A' and T.AssetID is null;
update H set H.UpdateHash = '0' from integration.AssetHash H inner join #Assets C on C.SourceID = H.SourceID and C.ParentSourceID is not null left join Asset P on P.SourceID = C.ParentSourceID where H.Section = @Section and H.RequestNumber = @RequestNumber and P.ID is null;
if @ParentIntersectTypeID is not null begin insert into integration.UnresolvedRelationships ( FieldName, IntersectTypeID, SourceID, ObjectAssetTypeID, ObjectSourceID, ObjectAssetID, Object, ObjectID, [Action] ) select '_context', @ParentIntersectTypeID, C.SourceID, @AssetTypeID, C.SourceID, C.AssetID, C.Object, C.ObjectID, C.[Action] from #Assets C where C.ParentSourceID not in (select SourceID from Asset);
-- ERROR CODE: 5 insert into integration.ExecutionAssetTypeError (ExecutionID, SynchedAssetTypeID, SourceID, ErrorMessages, ErrorCode) select @ExecutionID, @SynchedAssetTypeID, SourceID, '{ "IntersectTypeID": ' + cast(@ParentIntersectTypeID as nvarchar) + ', "Subject": "' + coalesce(ParentSourceID,'') + '", "Object": "' + coalesce(SourceID,'') + '" }', 5 as ErrorCode from #Assets where ParentSourceID not in (select SourceID from Asset); end;
select SourceID, AssetID, Object, ObjectID, Type, TypeID, [Action] from #Assets where [Action] = 'A' and [Action] is not null end
if @Section = 1 begin drop table if exists #Field; create table #Field ( AssetTypeID int, SourceID nvarchar(250), AssetID bigint, Object varchar(50), ObjectID int, FieldTypeID int, SourceFieldName nvarchar(250), RawValue nvarchar(max), [ParentContextPosition] int, [IsArray] bit, DefaultValue nvarchar(250), [ArrayValueDelimiter] varchar(10), [ArrayValueFieldName] varchar(50), NewValue nvarchar(max), [Action] char(1) );
CREATE NONCLUSTERED INDEX IX_TempField ON #Field ( [SourceFieldName], [ArrayValueDelimiter], [ArrayValueFieldName]) INCLUDE ([SourceID],[FieldTypeID],[RawValue]); CREATE NONCLUSTERED INDEX IX_TempField_FieldType_Object ON #Field (FieldTypeID ASC, Object ASC, ObjectID ASC) INCLUDE (NewValue); insert into #Field select @AssetTypeID as AssetTypeID, RF.SourceID, A.ID, A.Object, A.ObjectID, FT.ID, RF.FieldName, RF.FieldValue, F.[ParentContextPosition], F.[IsArray], F.DefaultValue, F.[ArrayValueDelimiter], F.[ArrayValueFieldName], NULL, NULL from [integration].[AssetHash] H inner join integration.AssetField RF on RF.SynchedAssetTypeID = H.SynchedAssetTypeID and RF.Section = H.Section and RF.SourceID = H.SourceID inner join [integration].[SynchedAssetTypeFieldItem] F on F.SynchedAssetTypeID = RF.SynchedAssetTypeID and F.SourceField = RF.FieldName and F.Active = 1 inner join Asset A on A.AssetTypeID = @AssetTypeID and A.SourceID = RF.SourceID left join FieldType FT on FT.AssetTypeID = @AssetTypeID and FT.Name = F.TargetField where H.SynchedAssetTypeID = @SynchedAssetTypeID and H.Section = @section and H.RequestNumber = @RequestNumber and H.[Action] in ('A', 'U'); BEGIN update T set NewValue = S.NewValue from #Field T inner join ( select J.SourceID, J.FieldTypeID, STRING_AGG(P.Val, ' / ') as NewValue from #Field J cross apply OPENJSON(J.RawValue) C cross apply OPENJSON(c.value) with (Val nvarchar(500) '$._name') P where ISJSON(J.RawValue) = 1 and SourceFieldName = '_context' and ArrayValueDelimiter is not null and ArrayValueFieldName is not null group by J.SourceID, J.FieldTypeID ) S on S.SourceID = T.SourceID and S.FieldTypeID = T.FieldTypeID; END
BEGIN update #Field set NewValue = case when RawValue is null and DefaultValue is not null then DefaultValue when RawValue is null and DefaultValue is null then null when RawValue = '' and DefaultValue is not null then DefaultValue when RawValue = '' and DefaultValue is null then null else RawValue end where FieldTypeID is not null and IsArray = 0; END BEGIN declare @Enums nvarchar(max) select @Enums = EnumFieldValues from integration.ExecutionAssetType where ExecutionID = @ExecutionID and SynchedAssetTypeID = @SynchedAssetTypeID drop table if exists #EnumValueTable; create table #EnumValueTable (PropertyName nvarchar(250), Code nvarchar(100), DisplayValue nvarchar(500)) CREATE CLUSTERED INDEX CIX_TempEnumValueTable ON #EnumValueTable (PropertyName, Code); insert into #EnumValueTable select * from OPENJSON(@Enums) with (PropertyName nvarchar(250) '$.PropertyName', Code nvarchar(100) '$.Code', DisplayValue nvarchar(500) '$.DisplayValue')
update T set T.NewValue = S.NewValue from #Field T inner join ( select SourceID, SourceFieldName, E.DisplayValue as NewValue from #Field J inner join #EnumValueTable E on E.PropertyName = J.SourceFieldName and E.Code = J.RawValue where FieldTypeID is not null and IsArray = 0 ) S on S.SourceID = T.SourceID and S.SourceFieldName = T.SourceFieldName;
update T set T.NewValue = S.NewValue from #Field T inner join ( select SourceID, SourceFieldName, STRING_AGG(E.DisplayValue, ', ') WITHIN GROUP ( ORDER BY E.DisplayValue ASC ) as NewValue from #Field J cross apply OPENJSON(J.RawValue) RV
inner join #EnumValueTable E on E.PropertyName = J.SourceFieldName and E.Code = RV.value where ISJSON(J.RawValue) = 1 and FieldTypeID is not null and IsArray = 1 and ArrayValueDelimiter is null
group by AssetTypeID, SourceID, SourceFieldName ) S on S.SourceID = T.SourceID and S.SourceFieldName = T.SourceFieldName; END BEGIN declare @ObjToUpdate varchar(50) drop table if exists #ObjectsToUpdateDateOn create table #ObjectsToUpdateDateOn (Object varchar(50), ObjectID int, SourceID nvarchar(250)); CREATE CLUSTERED INDEX CIX_TempObjectsToUpdateDateOn ON #ObjectsToUpdateDateOn (ObjectID); CREATE NONCLUSTERED INDEX IX_TempObjectsToUpdateDateOn_SourceID ON #ObjectsToUpdateDateOn (SourceID); insert into #ObjectsToUpdateDateOn select distinct N.Object, N.ObjectID, N.SourceID from #Field N left join Field E on E.ObjectType = N.Object and E.ObjectID = N.ObjectID and E.FieldTypeID = N.FieldTypeID where N.FieldTypeID is not null and ( (E.ID is not null and N.NewValue <> E.Value) or E.ID is null ); select top 1 @ObjToUpdate = Object from #ObjectsToUpdateDateOn
update T set T.[UpdatedBy] = @ResourceID, T.[UpdatedOn] = @date from Asset T inner join #ObjectsToUpdateDateOn S on T.[Object] = @ObjToUpdate and S.ObjectID = T.ObjectID;
if @ObjToUpdate = 'Rule' begin update T set T.[UpdatedBy] = @ResourceID, T.[UpdatedOn] = @date from dbo.[Rule] T inner join #ObjectsToUpdateDateOn S on S.ObjectID = T.ID; end END;
merge into Field T using ( select * from #Field where FieldTypeID is not null ) S on ( T.FieldTypeID = S.FieldTypeID and T.ObjectType = S.Object and T.ObjectID = S.ObjectID ) when matched and ( (T.Value <> S.NewValue) OR (T.Value is null) OR (S.NewValue is null and T.Value is not null) ) then update set T.Value = S.NewValue, T.FormattedValue = S.NewValue, T.UpdatedBy = @ResourceID, T.UpdatedOn = @date when not matched by target then insert (FieldTypeID, ObjectType, ObjectID, Value, FormattedValue, UpdatedBy, UpdatedOn) values (S.FieldTypeID, S.Object, S.ObjectID, S.NewValue, S.NewValue, @ResourceID, @date);
update T set T.[Hash] = T.UpdateHash from integration.AssetHash T inner join #ObjectsToUpdateDateOn S on T.SynchedAssetTypeID = @SynchedAssetTypeID and S.SourceID = T.SourceID and T.Section = @section and T.RequestNumber = @RequestNumber;
update T set T.[Hash] = T.UpdateHash from integration.AssetHash T inner join #Field F on F.SourceID = T.SourceID and T.Section = @section and T.RequestNumber = @RequestNumber and T.SynchedAssetTypeID = @SynchedAssetTypeID and F.FieldTypeID is null and F.SourceFieldName = '_name'; end
if @section = 2 begin drop table if exists #Rel_Step1; create table #Rel_Step1 ( SourceID nvarchar(250), FieldName nvarchar(250), IntersectTypeID int, IsSubject bit, SubjectAssetTypeID int, SubjectSourceID nvarchar(250), SubjectAssetID bigint, Subject varchar(50), SubjectID int, ObjectAssetTypeID int, ObjectSourceID nvarchar(250), ObjectAssetID bigint, Object varchar(50), ObjectID int, [Action] char(1) ); CREATE NONCLUSTERED INDEX IX_TempRel_Step1 ON #Rel_Step1 (IntersectTypeID);
BEGIN insert into #Rel_Step1 select H.SourceID ,RF.FieldName ,IT.ID ,R.IsSubject ,ST.ID, IIF(R.IsSubject=1,H.SourceID,RIIF._id), SA.ID, SA.Object, SA.ObjectID ,OT.ID, IIF(R.IsSubject=0,H.SourceID,RIIF._id), OA.ID, OA.Object, OA.ObjectID ,H.[Action] from [integration].[AssetHash] H inner join integration.AssetField RF on RF.SynchedAssetTypeID = H.SynchedAssetTypeID and RF.Section = H.Section and RF.SourceID = H.SourceID inner join [integration].[SynchedAssetTypeRelationItem] R on R.SynchedAssetTypeID = RF.SynchedAssetTypeID and R.[SourceField] = RF.FieldName cross apply OPENJSON(RF.FieldValue) with (_type nvarchar(max) '$._type', _id nvarchar(max) '$._id') RIIF inner join [integration].[SynchedAssetTypeRelationItemTarget] RT on RT.[SynchedAssetTypeRelationItemID] = R.ID and RIIF._type = RT.[SourceAssetType] inner join IntersectType IT on IT.ID = RT.IntersectTypeID inner join AssetType ST on ST.Object = IT.Subject and ST.ObjectID = IT.SubjectID inner join AssetType OT on OT.Object = IT.Object and OT.ObjectID = IT.ObjectID left join Asset SA on SA.AssetTypeID = ST.ID and SA.SourceID = IIF(R.IsSubject=1,H.SourceID,RIIF._id) left join Asset OA on OA.AssetTypeID = OT.ID and OA.SourceID = IIF(R.IsSubject=0,H.SourceID,RIIF._id) where H.SynchedAssetTypeID = @SynchedAssetTypeID and H.Section = @section and H.RequestNumber = @RequestNumber and H.[Action] in ('A', 'U') and RIIF._type is not null and RIIF._id not like 'extern:fr:%'; END drop table if exists #Rel_Step2; create table #Rel_Step2 ( SourceID nvarchar(250), FieldName nvarchar(250), IntersectTypeID int, SubjectAssetTypeID int, SubjectSourceID nvarchar(250), SubjectAssetID bigint, Subject varchar(50), SubjectID int, ObjectAssetTypeID int, ObjectSourceID nvarchar(250), ObjectAssetID bigint, Object varchar(50), ObjectID int, IntersectID int, [Action] char(1) ); CREATE NONCLUSTERED INDEX IX_TempRel_Step2_SubjectObject_Include ON #Rel_Step2 ([Action],[Subject],[SubjectID],[Object],[ObjectID]) INCLUDE ([IntersectTypeID]);
BEGIN
insert into #Rel_Step2 select S.SourceID ,S.FieldName ,S.IntersectTypeID ,S.SubjectAssetTypeID ,S.SubjectSourceID ,S.SubjectAssetID ,S.Subject ,S.SubjectID ,S.ObjectAssetTypeID ,S.ObjectSourceID ,S.ObjectAssetID ,S.Object ,S.ObjectID ,I.ID ,S.[Action] from #Rel_Step1 S left join [Intersect] I on I.IntersectTypeID = S.IntersectTypeID and I.Subject = S.Subject and I.SubjectID = S.SubjectID and I.Object = S.Object and I.ObjectID = S.ObjectID; update #Rel_Step2 set [Action] = 'A' where IntersectID is null;
drop table if exists #Rel_Step1; END drop table if exists #IntersectTypes; create table #IntersectTypes (ID int); BEGIN insert into #IntersectTypes select RT.IntersectTypeID from [integration].[SynchedAssetTypeRelationItemTarget] RT inner join [integration].[SynchedAssetTypeRelationItem] R on R.ID = RT.[SynchedAssetTypeRelationItemID] and R.SynchedAssetTypeID = @SynchedAssetTypeID group by RT.IntersectTypeID; END
BEGIN update U set U.SubjectAssetID = A.ID, U.Subject = A.Object, U.SubjectID = A.ObjectID from integration.UnresolvedRelationships U inner join #IntersectTypes IT on IT.ID = U.IntersectTypeID and U.SubjectAssetID is null and (U.SubjectAssetTypeID = @AssetTypeID OR U.ObjectAssetTypeID = @AssetTypeID) inner join Asset A on A.AssetTypeID = U.SubjectAssetTypeID and A.SourceID = U.SubjectSourceID;
update U set U.ObjectAssetID = A.ID, U.Object = A.Object, U.ObjectID = A.ObjectID from integration.UnresolvedRelationships U inner join #IntersectTypes IT on IT.ID = U.IntersectTypeID and U.ObjectAssetID is null and (U.SubjectAssetTypeID = @AssetTypeID OR U.ObjectAssetTypeID = @AssetTypeID) inner join Asset A on A.AssetTypeID = U.ObjectAssetTypeID and A.SourceID = U.ObjectSourceID;
insert into #Rel_Step2 select SourceID ,FieldName ,U.IntersectTypeID ,SubjectAssetTypeID ,SubjectSourceID ,SubjectAssetID ,Subject ,SubjectID ,ObjectAssetTypeID ,ObjectSourceID ,ObjectAssetID ,Object ,ObjectID ,null ,[Action] from integration.UnresolvedRelationships U inner join #IntersectTypes IT on IT.ID = U.IntersectTypeID and SubjectAssetID is not null and ObjectAssetID is not null; delete integration.UnresolvedRelationships where SubjectAssetID is not null and ObjectAssetID is not null; END
BEGIN insert into [Intersect] (IntersectTypeID, Subject, SubjectID, Object, ObjectID, CreatedBy, UpdatedBy) select distinct T.IntersectTypeID, T.Subject, T.SubjectID, T.Object, T.ObjectID, @ResourceID, @ResourceID from #Rel_Step2 T left join [Intersect] S on T.[Action] = 'A' and S.IntersectTypeID = T.IntersectTypeID and S.Subject = T.Subject and S.SubjectID = T.SubjectID and S.Object = T.Object and S.ObjectID = T.ObjectID where T.[Action] = 'A' and T.Subject is not null and T.SubjectID is not null and T.Object is not null and T.ObjectID is not null and S.ID is null; END BEGIN update T set T.[State] = 1, T.Deleted = 0 from [Intersect] T inner join #Rel_Step2 S on S.IntersectID = T.ID and S.[Action] = 'U' and (T.Deleted = 1 or T.[State] <> 1); END BEGIN update T set T.IntersectID = S.ID from #Rel_Step2 T inner join [Intersect] S on T.[Action] = 'A' and S.IntersectTypeID = T.IntersectTypeID and S.Subject = T.Subject and S.SubjectID = T.SubjectID and S.Object = T.Object and S.ObjectID = T.ObjectID; END BEGIN insert into integration.ExecutionAssetTypeLog (ExecutionID, SynchedAssetTypeID, Section, [Action], [Log]) select @ExecutionID, @SynchedAssetTypeID, @section, [Action], '{' + '"SubjectSourceID": "' + SubjectSourceID + '", ' + '"ObjectSourceID": "' + ObjectSourceID + '", ' + '"IntersectID": "' + cast(IntersectID as nvarchar) + '"' + '}' as [Log] from #Rel_Step2 where [Action] = 'A' and IntersectID is not null; END BEGIN -- ERROR CODE: 6 insert into integration.ExecutionAssetTypeError (ExecutionID, SynchedAssetTypeID, SourceID, ErrorMessages, ErrorCode) select @ExecutionID, @SynchedAssetTypeID, SourceID, '{ "Field": "' + coalesce(FieldName,'') + '", "Subject": "' + coalesce(SubjectSourceID,'') + '", "Object": "' + coalesce(ObjectSourceID,'') + '" }', 6 as ErrorCode from #Rel_Step2 where [Action] = 'A' and (SubjectAssetID is null or ObjectAssetID is null) and IntersectID is null;
update #Rel_Step2 set [Action] = 'E' where [Action] = 'A' and (SubjectAssetID is null or ObjectAssetID is null) and IntersectID is null; END
BEGIN insert into integration.UnresolvedRelationships ( FieldName, IntersectTypeID, SourceID, SubjectAssetTypeID, SubjectSourceID, SubjectAssetID, Subject, SubjectID, ObjectAssetTypeID, ObjectSourceID, ObjectAssetID, Object, ObjectID, [Action] ) select R.FieldName, R.IntersectTypeID, R.SourceID, R.SubjectAssetTypeID, R.SubjectSourceID, R.SubjectAssetID, R.Subject, R.SubjectID, R.ObjectAssetTypeID, R.ObjectSourceID, R.ObjectAssetID, R.Object, R.ObjectID, R.[Action] from #Rel_Step2 R left join integration.UnresolvedRelationships EU on EU.IntersectTypeID = R.IntersectTypeID and EU.SourceID = R.SourceID and ( EU.SubjectAssetID = R.SubjectAssetID or EU.ObjectAssetID = R.ObjectAssetID ) where R.[Action] in ('A', 'U') and EU.ID is null and R.IntersectID is null; END
BEGIN update T set T.[Hash] = T.UpdateHash from integration.AssetHash T inner join ( select SourceID from #Rel_Step2 where [Action] in ('A', 'U', 'D') and IntersectID is not null and SourceID not in (select SourceID from #Rel_Step2 where [Action] <> 'E') group by SourceID ) S on T.SynchedAssetTypeID = @SynchedAssetTypeID and S.SourceID = T.SourceID and T.Section = @section and T.RequestNumber = @RequestNumber; END
select * from ( --select distinct -- IntersectTypeID, -- IntersectID, -- [Action] --from #Rel_Step2 --where [Action] not in ('N', 'E', 'A', '') -- and [Action] is not null -- and IntersectID is not null
--union select top 250 I.IntersectTypeID, I.ID as IntersectID, 'A' as [Action] from [workflow].[EventRegistration] ER inner join [Intersect] I on ER.Object = 'IntersectType' and I.IntersectTypeID = ER.ObjectID and ER.State = 1 inner join #IntersectTypes IT on IT.ID = I.IntersectTypeID inner join workflow.[Type] T on T.ID = ER.TypeID and T.State = 1 and T.CreatedOn < I.CreatedOn and I.CreatedOn <= DATEADD(mi, -60, @date) left join workflow.Item WI on WI.Object = 'Intersect' and WI.ObjectID = I.ID where WI.ID is null ) O order by O.IntersectID; end
if @section = 3 begin drop table if exists #Owners; create table #Owners (AssetID bigint, SourceID nvarchar(250), ResponsibilityTypeID int, ResourceIdentifier nvarchar(250), ResolutionFieldTypeID int, ResourceID int, [Action] varchar(1), Error varchar(max), OverrideItemID bigint); CREATE NONCLUSTERED INDEX IX_TempOwners_ResourceIdentifier ON #Owners (ResourceIdentifier) INCLUDE (AssetID, ResponsibilityTypeID, [Action]); CREATE NONCLUSTERED INDEX IX_TempOwners_ResourceID ON #Owners (ResourceID) INCLUDE (AssetID, ResponsibilityTypeID, [Action]); CREATE NONCLUSTERED INDEX IX_TempOwners_ResourceIDAction ON #Owners (ResourceID, [Action]) INCLUDE (AssetID, ResponsibilityTypeID); CREATE NONCLUSTERED INDEX IX_TempOwners_DeleteAndUpdateStepIndex ON #Owners (ResponsibilityTypeID, AssetID, [Action]); CREATE NONCLUSTERED INDEX IX_TempOwners_AddStepIndex ON #Owners ([Action]);
-- Resolution Type = 1 insert into #Owners (AssetID, SourceID, ResponsibilityTypeID, ResourceIdentifier, ResolutionFieldTypeID) select A.ID as AssetID ,substring(ltrim(rtrim(J.SourceID)), 1, 250) ,R.ResponsibilityTypeID ,substring(rtrim(ltrim(J.FieldValue)), 1, 250) ,R.ResolutionFieldTypeID from [integration].[AssetHash] H inner join integration.AssetField J on J.SynchedAssetTypeID = H.SynchedAssetTypeID and J.Section = H.Section and H.RequestNumber = @RequestNumber and J.SourceID = H.SourceID inner join Asset A on A.AssetTypeID = @AssetTypeID and A.SourceID = J.SourceID inner join [integration].[SynchedAssetTypeRoleItem] R on R.SynchedAssetTypeID = J.SynchedAssetTypeID and R.SourceIdField = J.FieldName and R.ResolutionType = 1 where H.SynchedAssetTypeID = @SynchedAssetTypeID and H.Section = @section and H.[Action] in ('A', 'U');
-- Resolution Type = 2 insert into #Owners (AssetID, SourceID, ResponsibilityTypeID, ResourceIdentifier, ResolutionFieldTypeID) select A.ID as AssetID ,substring(ltrim(rtrim(J.SourceID)), 1, 250) ,R.ResponsibilityTypeID ,S._id ,R.ResolutionFieldTypeID from [integration].[AssetHash] H inner join integration.AssetField J on J.SynchedAssetTypeID = H.SynchedAssetTypeID and J.Section = H.Section and H.RequestNumber = @RequestNumber and J.SourceID = H.SourceID inner join Asset A on A.AssetTypeID = @AssetTypeID and A.SourceID = J.SourceID inner join [integration].[SynchedAssetTypeRoleItem] R on R.SynchedAssetTypeID = J.SynchedAssetTypeID and R.SourceIdField = J.FieldName and R.ResolutionType = 2 cross apply OPENJSON(J.FieldValue) SR cross apply OPENJSON(SR.[value]) with (_id nvarchar(max) '$._id') S where ISJSON(J.FieldValue) = 1 and H.SynchedAssetTypeID = @SynchedAssetTypeID and H.Section = @section and H.[Action] in ('A', 'U') and SR.[key] = 'items' and SR.[value] <> '[]';
-- Set to remove any that are now empty that may have previously been populated. update #Owners set [Action] = 'D' where ResourceIdentifier is null or ResourceIdentifier = '';
-- Populate the resource ID for the user, those that can resolve. update T set T.ResourceID = RE.ResourceID from #Owners T inner join Field F on F.ObjectType = 'Resource' and F.Value = T.ResourceIdentifier and F.FieldTypeID = T.ResolutionFieldTypeID inner join reporting.Global_Resource RE on RE.ResourceID = F.ObjectID;
-- Log errors for resource identifiers that cannot be resolved. BEGIN if @IsFullRefresh = 0 begin insert into integration.ExecutionAssetTypeError (ExecutionID, SynchedAssetTypeID, SourceID, ErrorMessages, ErrorCode) select @ExecutionID, @SynchedAssetTypeID, H.SourceID, ( select ResponsibilityTypeID, ResourceIdentifier from #Owners where SourceID = H.SourceID and ResourceIdentifier is not null and ResourceIdentifier <> '' and ResourceID is null for json path ) as ErrorMessages, 7 as ErrorCode from #Owners H where ResourceIdentifier is not null and ResourceIdentifier <> '' and ResourceID is null group by SourceID; end
update #Owners set [Action] = 'D', [Error] = 'User could not be found based on identifier [' + coalesce(ResourceIdentifier,'') + '].' where ResourceIdentifier is not null and ResourceIdentifier <> '' and ResourceID is null; END
-- Mark the same entries as having not been changed. update T set T.[Action] = 'N' from #Owners T inner join ResponsibilityTypeRelationOverrideItem S on S.AssetID = T.AssetID and S.ResponsibilityTypeID = T.ResponsibilityTypeID and S.SecurityAsset = 'R' and S.SecurityAssetID = T.ResourceID and T.ResourceID is not null;
-- Mark as [U]pdated those entries where the ResourceID has changed. ----update T ----set T.[Action] = 'U' ----from #Owners T ---- inner join ResponsibilityTypeRelationOverrideItem S on S.AssetID = T.AssetID and S.ResponsibilityTypeID = T.ResponsibilityTypeID and S.SecurityAsset = 'R' and S.SecurityAssetID <> T.ResourceID ----where T.ResourceID is not null ---- and T.[Action] is null;
-- Mark as [A]dded those entries where the override record does not exist but should. update T set T.[Action] = 'A' from #Owners T left join ResponsibilityTypeRelationOverrideItem S on S.AssetID = T.AssetID and S.ResponsibilityTypeID = T.ResponsibilityTypeID and S.SecurityAsset = 'R' and S.SecurityAssetID = T.ResourceID --this line is new where T.ResourceID is not null and T.[Action] is null and T.AssetID is not null and S.[ID] is null;
--Figure out records currently in system that are no longer valid. --NEW insert into #Owners (AssetID, SourceID, ResponsibilityTypeID, ResourceID, [Action]) select T.AssetID, R.SourceID, T.ResponsibilityTypeID, T.SecurityAssetID, 'D' as [Action] from ResponsibilityTypeRelationOverrideItem T inner join #Owners R on R.ResponsibilityTypeID = T.ResponsibilityTypeID and R.AssetID = T.AssetID --Restrict to ONLY the assets and responsibilitites we currently have loaded into temp table. left join #Owners S on S.ResponsibilityTypeID = T.ResponsibilityTypeID and S.AssetID = T.AssetID and T.SecurityAsset = 'R' and T.SecurityAssetID = S.ResourceID where S.AssetID is null;
-- Save changes to Log. BEGIN insert into integration.ExecutionAssetTypeLog (ExecutionID, SynchedAssetTypeID, Section, [Action], [Log]) select @ExecutionID, @SynchedAssetTypeID, @section, [Action], '{' + '"SourceID": "' + SourceID + '", ' + '"ResourceIdentifier": "' + ResourceIdentifier + '", ' + '"ResponsibilityTypeID": "' + cast(ResponsibilityTypeID as nvarchar) + '"' + '}' as [Log] from #Owners where [Action] <> 'N' and SourceID is not null and ResourceIdentifier is not null; END
delete T from ResponsibilityTypeRelationOverrideItem T inner join #Owners S on S.ResponsibilityTypeID = T.ResponsibilityTypeID and S.AssetID = T.AssetID and S.[Action] = 'D' and T.SecurityAsset = 'R' and S.ResourceID = T.SecurityAssetID; --new line
----update T ----set T.SecurityAssetID = S.ResourceID ----from ResponsibilityTypeRelationOverrideItem T ---- inner join #Owners S on S.ResponsibilityTypeID = T.ResponsibilityTypeID and S.AssetID = T.AssetID and S.[Action] = 'U' and T.SecurityAsset = 'R';
insert into ResponsibilityTypeRelationOverrideItem (ResponsibilityTypeID, AssetID, SecurityAsset, SecurityAssetID) select ResponsibilityTypeID, AssetID, 'R' as SecurityAsset, ResourceID from #Owners where [Action] = 'A';
-- Delete any duplicates that may have been introduced. delete ResponsibilityTypeRelationOverrideItem where ID in ( select max(ID) as ID from ResponsibilityTypeRelationOverrideItem group by ResponsibilityTypeID, AssetID, SecurityAsset, SecurityAssetID having count(1) > 1 );
update T set T.[Hash] = T.UpdateHash from integration.AssetHash T inner join #Owners S on T.SynchedAssetTypeID = @SynchedAssetTypeID and S.SourceID = T.SourceID and T.Section = @section and T.RequestNumber = @RequestNumber and S.[Action] in ('A', 'U', 'D') and S.OverrideItemID is not null; end
end
